void opeu_bomb_animate(uint8_t ds[65536], HostEvent event, uint16_t load,
                       uint16_t bp, UNIT_P unit, uint8_t side) {
  WORD_LOCAL(px, 2);
  WORD_LOCAL(py, 4);
  uint16_t ux, uy, fy;
  ux = UNIT_X(unit);
  uy = UNIT_Y(unit);
  SET_MAP_MODE(1);
  FOCUS(ux, uy, SIDE_FOR_STATUS(side));
  SET_VAL(px, ux);
  SET_VAL(py, uy);
  CELL_PIXELS(REF(px), REF(py));
  ADD_VAL(py, 8);
  for (fy = 348; fy >= VAL(py); fy--) {
    DRAW_FRAME(VAL(px), fy);
    if ((uint16_t)(VAL(py) - fy) == (uint16_t)-32)
      CUE4();
    DELAY(1);
    RESTORE_FRAME(VAL(px), fy);
  }
  MUSIC7();
}

