void opeu_bomb_event(uint8_t ds[65536], HostEvent event, uint16_t load,
                     uint16_t bp) {
  BUFFER(report, 90, 0xce);
  uint16_t rate;
  BUFFER(intro, 90, 0x72);
  BUFFER(unit_nm, 12, 0x18);
  PERSON_P person;
  uint8_t  saved_mode, voice, side, b;
  UNIT_P   troop;
  if ((SCENARIO & 0x7f) != 3)
    return;
  if (MONTH < 6 || (MONTH == 6 && DAY < 13))
    return;
  if (!DAYTIME(HOUR))
    return;
  if (WEATHER != 0 && WEATHER != 1)
    return;
  rate = CONTROL(1) == 1 ? LEVEL : 2;
  for (side = 0; side < 4; side++) {
    for (troop = GROUP_UNITS(side + 4), b = 0; b < 8; NEXT_UNIT(troop), b++) {
      if (!(UNIT_FLAGS(troop) & 4) || !SPECIAL(troop) ||
          RANDOM(150 - rate * 20))
        continue;
      UNIT_NAME(troop, unit_nm);
      if (STATUS(0) == 1) {
        voice = 0;
        COPY(intro, LOOKUP(0x21));
        FORMAT(report, LOOKUP(0x22), unit_nm);
      } else if (STATUS(1) == 1 && ELIGIBLE(troop)) {
        voice = 1;
        COPY(intro, LOOKUP(0x23));
        FORMAT(report, LOOKUP(0x24), unit_nm);
      } else
        voice = 0xff;
      saved_mode = MAP_MODE;
      if (voice != 0xff) {
        person = SIDE_RECORD(voice, 3);
        MESSAGE(intro, person);
        SHOW_PRESENT(0x1c7, 0);
        ANIMATE(troop, voice);
        MESSAGE(report, person);
      }
      CASUALTIES(troop, 15, 30, 10, 0, 1);
      SET_MAP_MODE(saved_mode);
    }
  }
}

